const e=JSON.parse(JSON.stringify($json));
const i=e.intelligence??{};
const sig=i.response_signals??{};
const dealer=e.context?.dealer??{};
const inv=e.inventory??{status:'UNKNOWN'};
const resolution=e.context?.resolution??{};
const contextCustomer=e.context?.customer??{};
const lead=e.context?.lead??{};
const meaningful=value=>value!==null&&value!==undefined&&(typeof value!=='string'||value.trim()!=='');
const firstMeaningful=(...values)=>values.find(meaningful)??null;
const customer={name:i.customer?.name??contextCustomer.name??lead.name??null,email:i.customer?.email??contextCustomer.email??lead.email??null,phone:firstMeaningful(i.customer?.phone,contextCustomer.phone,lead.phone,e.event?.sender)};
const vehicle={vin:i.vehicle?.vin??lead.vin??null,year:i.vehicle?.year??lead.year??null,make:i.vehicle?.make??lead.make??null,model:i.vehicle?.model??lead.model??null};
const hasKnownVehicle=Object.values(vehicle).some(meaningful);
const isEmail=i.communication?.preferred_mode==='email'&&!!customer.email;
const resolutionInvalid=resolution.valid===false;
const resolutionAmbiguous=resolution.ambiguous===true||resolution.customer_ambiguous===true||resolution.lead_ambiguous===true;
const identityUnsafe=resolutionInvalid||resolutionAmbiguous;
const escalationRequired=i.escalation?.required===true||i.journey?.intent==='Managerial Review';
const appointmentSignal=i.appointment?.signal??'NONE';
const booked=i.journey?.intent==='Visit Booked'||appointmentSignal==='BOOKED';
const visitBehavior=i.journey?.intent==='Visit Requested'||['INTEREST','ACCEPT','RESCHEDULE','CANCEL'].includes(appointmentSignal);
const inventoryIntent=['Availability Inquiry','Price Inquiry','Test Drive Request'].includes(i.inquiry?.category)||inv.required===true;
let route='GENERAL';
if(i.dnd?.requested===true)route='DND';
else if(identityUnsafe)route='ESCALATION';
else if(escalationRequired)route='ESCALATION';
else if(isEmail)route='EMAIL_HANDOFF';
else if(booked)route='BOOKING';
else if(visitBehavior)route='VISIT';
else if(inventoryIntent)route='INVENTORY';
const links={vdp:null,trade:null,finance:null,booking:null,store_website:null};
if(sig.asks_vdp_content)links.vdp=inv.exact_vehicle?.vdp_url??inv.alternatives?.[0]?.vdp_url??null;
if(sig.complex_trade)links.trade=dealer.trade_url??null;
if(sig.complex_finance)links.finance=dealer.finance_url??null;
if(sig.asks_booking_link)links.booking=dealer.booking_url??null;
if(route==='ESCALATION')links.store_website=inv.exact_vehicle?.vdp_url??dealer.store_website??null;
const inventoryWarnings=Array.isArray(inv.warnings)?inv.warnings:[];
const exactMatchCount=Array.isArray(inv.exact_matches)?inv.exact_matches.length:0;
const noInventoryKey=inv.status==='NO_INVENTORY_KEY'||inventoryWarnings.includes('NO_INVENTORY_KEY');
const noInventoryMatch=inv.status==='NO_MATCH'||inventoryWarnings.includes('NO_INVENTORY_MATCH');
const inventoryContradiction=hasKnownVehicle&&noInventoryKey;
let inventoryClaimMode='not_applicable';
if(inv.status==='EXACT_AVAILABLE')inventoryClaimMode=inv.authoritative_availability===true?'confirmed_available':'availability_unverified';
else if(inv.status==='EXACT_UNAVAILABLE')inventoryClaimMode=inv.authoritative_availability===true?'confirmed_unavailable':'availability_unverified';
else if(exactMatchCount>0)inventoryClaimMode='availability_unverified';
else if(inv.status==='ALTERNATIVES')inventoryClaimMode='alternatives_only';
else if(noInventoryMatch)inventoryClaimMode='no_match';
else if(inventoryIntent)inventoryClaimMode='insufficient_vehicle_context';
let cta='answer_question';
if(route==='VISIT')cta=appointmentSignal==='RESCHEDULE'?'reschedule':appointmentSignal==='CANCEL'?'cancel_appointment':'book_appointment';
if(route==='BOOKING')cta='confirm_appointment';
if(route==='INVENTORY'){
  if(inventoryContradiction)cta='verify_availability';
  else if(inv.status==='EXACT_AVAILABLE')cta=inv.authoritative_availability===true?(sig.explicit_visit_refusal?'answer_question':'offer_visit'):'verify_availability';
  else if(inv.status==='EXACT_UNAVAILABLE')cta=inv.authoritative_availability===true?'offer_alternatives':'verify_availability';
  else if(inv.status==='ALTERNATIVES'||noInventoryMatch)cta='offer_alternatives';
  else if(exactMatchCount===1)cta='verify_availability';
  else if(exactMatchCount>1)cta='clarify_vehicle';
  else cta=hasKnownVehicle?'verify_availability':'clarify_vehicle';
}
if(route==='ESCALATION')cta='human_follow_up';
if(route==='EMAIL_HANDOFF')cta='email_follow_up';
if(route==='DND')cta='none';
const toneByInquiry={'Price Inquiry':'consultative','Availability Inquiry':'helpful','Test Drive Request':'enthusiastic','Financing/Loan Inquiry':'supportive','Trade-In Inquiry':'consultative','Service Inquiry':'service-friendly','Warranty Inquiry':'reassuring','Managerial Review':'escalation','Hidden Price Concern':'transparent','Sarcasm / Frustration':'calm-empathetic','Already Purchased':'courteous-close','Closing':'assumptive-warm','Negotiation':'consultative-firm','Delivery / Pickup':'logistics-friendly','General Inquiry':'neutral'};
const objective={DND:'Do not send a customer response. Preserve v7 DND handling and prepare the manager notification.',ESCALATION:'Tell the customer a dealership team member will follow up shortly; do not promise a precise time.',EMAIL_HANDOFF:'Create the existing email-preference response using the supplied email and approved facts.',BOOKING:'Confirm only the date/time actually supplied or clearly established; otherwise ask for a preferred day/time using existing v7 booking behavior.',VISIT:'Handle the supported appointment signal using existing store-hours/date rules without inventing availability or continuing after refusal.',INVENTORY:'Answer only from the structured inventory status and use the selected inventory claim mode and CTA without repeating a declined visit.',GENERAL:'Answer the current message directly and concisely, using context to avoid repetition.'}[route];
const LEAD_NOTES_LIMIT=12;
const leadNotes=Array.isArray(e.context?.lead_notes)?e.context.lead_notes:[];
const approved={current_message:e.event?.content??'',customer:{name:customer.name,email:customer.email,phone:customer.phone},vehicle,inventory:inv,dealer:{bot_name:dealer.bot_name??null,store_name:dealer.store_name??null,store_phone:dealer.store_phone??null,store_address:sig.asks_location?dealer.store_address??null:null,store_hours:dealer.store_hours??[],store_hours_text:dealer.store_hours_text??null,timezone:dealer.timezone??null},conversation:{sms:(e.context?.sms_history??[]).slice(-12),email:(e.context?.email_history??[]).slice(-6),lead_notes:leadNotes.slice(-LEAD_NOTES_LIMIT),campaign:e.context?.campaign??null,attachments:e.context?.attachments??[]},appointment:i.appointment??{},links};
const vdp=inv.exact_vehicle?.vdp_url??inv.alternatives?.[0]?.vdp_url??'Not Available';
const name=approved.customer.name??'Not Provided';
const needsManager=i.dnd?.requested===true||identityUnsafe||escalationRequired;
const managerSms=i.dnd?.requested===true?'Lead opted for DND — Customer Name: "'+name+'". VDP: '+vdp+'. DND Reason - "'+(i.dnd?.reason??'Not Provided')+'"':needsManager?'New Lead Needs Intervention — Customer Name: "'+name+'". VDP: '+vdp+'. Full details sent on mail.':null;
const identitySafetyState=resolutionInvalid?'INVALID':resolutionAmbiguous?'AMBIGUOUS':resolution.valid===true?'VALID':'UNVERIFIED';
const warnings=[];
if(resolutionInvalid)warnings.push(...(resolution.errors?.length?resolution.errors:['INVALID_RESOLUTION']));
if(resolutionAmbiguous){
  warnings.push('AMBIGUOUS_IDENTITY_RESOLUTION');
  if(resolution.customer_ambiguous===true)warnings.push('AMBIGUOUS_CUSTOMER_IDENTITY');
  if(resolution.lead_ambiguous===true)warnings.push('AMBIGUOUS_LEAD_IDENTITY');
}
if(inventoryContradiction)warnings.push('INVENTORY_KEY_STATE_CONTRADICTION');
warnings.push(...inventoryWarnings);
e.decision={route,cta_type:cta,language:i.language?.confidence>=0.5?(i.language?.name??'English'):'English',language_code:i.language?.confidence>=0.5?(i.language?.code??'en'):'en',tone:toneByInquiry[i.inquiry?.category]??'neutral',response_objective:objective,allowed_facts:approved,allowed_links:Object.values(links).filter(Boolean),legacy_output_variant:route,max_characters:300,compatibility:{effective_v7_character_limit:300,prompted_v7_character_limit:160,lead_status_semantics:'preserved',lead_notes_limit:LEAD_NOTES_LIMIT},inventory_claim_mode:inventoryClaimMode,identity_safety_state:identitySafetyState,send_user_response:route!=='DND'&&!identityUnsafe,send_manager_sms:needsManager,manager_sms:managerSms,block_delivery:identityUnsafe,warnings:[...new Set(warnings)]};
return [{json:e}];
